package controlador; import java.io.IOException; import jakarta.servlet.*; import jakarta.servlet.http.*; import modelo.CitaDAO; public class CancelarCita extends HttpServlet{protected void processRequest(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{new CitaDAO().cambiarEstado(Integer.parseInt(r.getParameter("id")),"Cancelada");s.sendRedirect("misCitasCliente.jsp");} @Override protected void doGet(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{processRequest(r,s);}}
